const wh = $('ManyChat Webhook').first().json;
const rec = $('חיפוש לקוח קיים').first().json.records[0];
const existingLog = (rec.fields['WhatsApp Comments Log'] || '').trim();

const now = new Date();
const ts = now.toLocaleString('he-IL', {
  timeZone: 'Asia/Jerusalem',
  day: '2-digit', month: '2-digit', year: 'numeric',
  hour: '2-digit', minute: '2-digit'
});

const q = '"';
const newLine = '[' + ts + '] פלטפורמה: ' + (wh.platform || '') + ' | פוסט: ' + (wh.post_url || '') + ' | הודעה: ' + q + (wh.trigger_message || '') + q;
const updatedLog = existingLog ? newLine + '\n' + existingLog : newLine;

return [{
  json: {
    recordId: rec.id,
    fields: {
      'Source Platform': wh.platform || '',
      'Source Post URL': wh.post_url || '',
      'DM Keyword Used': wh.dm_keyword || '',
      'Source Content ID': wh.content_id || '',
      'ManyChat Subscriber ID': wh.subscriber_id || '',
      'Last Attribution Date': now.toISOString(),
      'WhatsApp Comments Log': updatedLog
    }
  }
}];

